  if e['type']=='turn_context':contexts.append({k:q.get(k) for k in ['model','effort','approval_policy','sandbox_policy']})
 out.append({'thread':spec['thread_id'],'path':str(path),'timestamp':meta.get('timestamp'),'base_sha256':hashlib.sha256(json.dumps(meta.get('base_instructions'),sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()).hexdigest(),'cli':meta.get('cli_version'),'developer':dev,'user_count':len(users),'first_users':users[:3],'refresh_hints':[u for u in users if u['refresh_hint']],'contexts_unique':[json.loads(k) for k in sorted(set(json.dumps(c,sort_keys=True) for c in contexts))]})
print(json.dumps({'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'run_id':rid,'records':out},indent=2))
trace=pathlib.Path(v['trace']['path']);print('TRACE_FIRST',next(trace.open())[:3500])
