python3 - <<'PY'
import json,pathlib,hashlib,datetime,re
s=pathlib.Path('bench-results/efficiency-mechanism-isolation-20260906T214448Z');out=[]
for phase in ['review-evidence-02','review-evidence-01']:
 p=s/'phases'/phase
 for source in sorted((p/'postcapture').glob('*/SOURCE-INPUT.json')):
  v=json.loads(source.read_text());authors=[];reviews=[];refreshes=[]
  for spec in v['native_sessions']:
   f=pathlib.Path(spec['source']['path']);raw=f.read_bytes();assert hashlib.sha256(raw).hexdigest()==spec['source']['sha256']
   rows=[json.loads(x) for x in raw.splitlines()];users=[]
   for n,e in enumerate(rows,1):
    q=e.get('payload',{})
    if e['type']=='response_item' and q.get('type')=='message' and q.get('role')=='user':
     body='\n'.join(c.get('text','') for c in q.get('content',[]) if 'text' in c)
     users.append((n,e.get('timestamp'),body))
   role='other';launch=users[1] if len(users)>1 else (0,'','')
   agent_ids=re.findall(r'(?m)^Agent-ID: (.+)$',launch[2]);features=re.findall(r'(?m)^Feature: (.+)$',launch[2])
   assert agent_ids and features
   if features[0]=='user-agent':role='author';authors.append({'thread':spec['thread_id'],'at':launch[1],'path':str(f)})
   elif features[0].startswith('review '):role='review';reviews.append({'thread':spec['thread_id'],'at':launch[1],'path':str(f),'agent_id':agent_ids[0]})
   if role=='author':
    for n,at,body in users:
     if body.startswith('The orchestrator could not apply your') and ('@@ ' in body or 'snapshot' in body.lower()):
      refreshes.append({'thread':spec['thread_id'],'line':n,'at':at,'bytes':len(body.encode()),'first':body[:650],'sha256':hashlib.sha256(body.encode()).hexdigest()})
  out.append({'phase':phase,'run':v['run_id'],'authors':authors,'reviews':reviews,'refreshes':refreshes,'source_path':str(source),'source_sha256':hashlib.sha256(source.read_bytes()).hexdigest()})
print(json.dumps({'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'retained source/input exposure lookup, no native audit or new model generation','rows':out},indent=2))
